 lossrows=['| 分量（实际进入总损失的权重已计入） | AB132损失贡献 | 参数梯度L2 | C42损失贡献 | 参数梯度L2 |','|---|---:|---:|---:|---:|'];names={'BCE_held_contribution':'held加权BCE / 3','BCE_in_contribution':'in加权BCE / 3','BCE_open_contribution':'open加权BCE / 3','latent_object_weighted':'对象SmoothL1 × 0.025','latent_scene_weighted':'场景SmoothL1 × 0.025'}
